INSERT INTO "task_participations" ("id", "task_id", "user_id", "status", "reward_snapshot", "reply_id", "submission", "claimed_at", "submitted_at", "completed_at") VALUES ('62be80f7-04c4-4364-bcbc-945fab233729', '00000000-0000-0000-0000-000000000023', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', 'rewarded', 180, NULL, '{}', '2026-07-21T07:09:59.218966+00:00', '2026-07-23T13:21:18.492144+00:00', '2026-07-23T13:21:18.492144+00:00') ON CONFLICT ("id") DO UPDATE SET "task_id" = EXCLUDED."task_id", "user_id" = EXCLUDED."user_id", "status" = EXCLUDED."status", "reward_snapshot" = EXCLUDED."reward_snapshot", "reply_id" = EXCLUDED."reply_id", "submission" = EXCLUDED."submission", "claimed_at" = EXCLUDED."claimed_at", "submitted_at" = EXCLUDED."submitted_at", "completed_at" = EXCLUDED."completed_at";
INSERT INTO "task_participations" ("id", "task_id", "user_id", "status", "reward_snapshot", "reply_id", "submission", "claimed_at", "submitted_at", "completed_at") VALUES ('0eeb3452-42ca-4ded-9faf-07f07ec41ab5', '00000000-0000-0000-0000-000000000020', '705c9595-ecc7-44cd-82fd-b3e6be27dd65', 'rewarded', 500, NULL, '{"body": "8.11 澳门尾场安可九，竟然唱到了第二天，幸福晕了🥰感谢乐队老师，浮夸！！！我还没有从武汉走出来，我又困在澳门了😭谁说我的老爱豆唱不上去的！！！无敌舞美，无敌 Live！！", "image_urls": ["data:image/jpeg;base64,"]}', '2026-07-20T15:44:41.986526+00:00', '2026-07-23T08:37:50.317896+00:00', '2026-07-23T08:37:50.317896+00:00') ON CONFLICT ("id") DO UPDATE SET "task_id" = EXCLUDED."task_id", "user_id" = EXCLUDED."user_id", "status" = EXCLUDED."status", "reward_snapshot" = EXCLUDED."reward_snapshot", "reply_id" = EXCLUDED."reply_id", "submission" = EXCLUDED."submission", "claimed_at" = EXCLUDED."claimed_at", "submitted_at" = EXCLUDED."submitted_at", "completed_at" = EXCLUDED."completed_at";
INSERT INTO "task_participations" ("id", "task_id", "user_id", "status", "reward_snapshot", "reply_id", "submission", "claimed_at", "submitted_at", "completed_at") VALUES ('2cf7bd00-46d8-4706-b81a-ce5309be05ae', '00000000-0000-0000-0000-000000000020', 'ecc39648-6ae9-47c8-8e79-af9ada827fe6', 'rewarded', 500, NULL, '{"body": "把一次现场相遇保存成长期粉丝记忆。提交内容由 AI Agent 检查相关性与灌水，通过后发放 FAN，并使用演唱会纪念图铸造一张限量 ERC-1155 纪念票。", "image_urls": []}', '2026-07-22T03:13:10.681578+00:00', '2026-07-23T05:44:27.966837+00:00', '2026-07-23T05:44:27.966837+00:00') ON CONFLICT ("id") DO UPDATE SET "task_id" = EXCLUDED."task_id", "user_id" = EXCLUDED."user_id", "status" = EXCLUDED."status", "reward_snapshot" = EXCLUDED."reward_snapshot", "reply_id" = EXCLUDED."reply_id", "submission" = EXCLUDED."submission", "claimed_at" = EXCLUDED."claimed_at", "submitted_at" = EXCLUDED."submitted_at", "completed_at" = EXCLUDED."completed_at";
