INSERT INTO "task_participations" ("id", "task_id", "user_id", "status", "reward_snapshot", "reply_id", "submission", "claimed_at", "submitted_at", "completed_at") VALUES ('e8d05774-eb65-49c7-83e5-57f478f23973', '00000000-0000-0000-0000-000000000021', '1385e9a6-dcec-4db0-a8cf-8302c9542f03', 'rewarded', 20, NULL, '{}', '2026-07-23T11:01:27.066505+00:00', '2026-07-23T11:01:27.077707+00:00', '2026-07-23T11:01:27.077707+00:00') ON CONFLICT ("id") DO UPDATE SET "task_id" = EXCLUDED."task_id", "user_id" = EXCLUDED."user_id", "status" = EXCLUDED."status", "reward_snapshot" = EXCLUDED."reward_snapshot", "reply_id" = EXCLUDED."reply_id", "submission" = EXCLUDED."submission", "claimed_at" = EXCLUDED."claimed_at", "submitted_at" = EXCLUDED."submitted_at", "completed_at" = EXCLUDED."completed_at";
INSERT INTO "task_participations" ("id", "task_id", "user_id", "status", "reward_snapshot", "reply_id", "submission", "claimed_at", "submitted_at", "completed_at") VALUES ('f15c0c44-cd7a-4a99-a35d-640b551bede1', '00000000-0000-0000-0000-000000000020', '1385e9a6-dcec-4db0-a8cf-8302c9542f03', 'rewarded', 500, NULL, '{"body": "FEAR and DREAMS · 现场瞬间\n\n那一晚《FEAR and DREAMS》的灯光熄灭时，全场突然安静下来，只剩下观众席此起彼伏的荧光点。我原本以为自己只是来听一场演唱会，但当陈奕迅唱到那句熟悉的歌词时，身边陌生人也跟着一起轻声合唱，我第一次真正感受到“几万人同时拥有同一种情绪”是什么样子。\n\n我记得最深的是副歌响起的瞬间，舞台的大屏从冷色调慢慢切换成温暖的光，整个体育馆像被一层记忆包裹住。那一刻我没有举手机录像，而是把手里的灯牌举高，认真地看完了整首歌。后来回想起来，我甚至记不清具体坐在哪一排，却能清楚记得当时胸口那种被音乐击中的感觉。\n\n很多人说演唱会结束后只剩散场的人潮，但《", "image_urls": ["data:image/jpeg;base64,"]}', '2026-07-23T11:01:28.718433+00:00', '2026-07-23T11:07:06.489720+00:00', '2026-07-23T11:07:06.489720+00:00') ON CONFLICT ("id") DO UPDATE SET "task_id" = EXCLUDED."task_id", "user_id" = EXCLUDED."user_id", "status" = EXCLUDED."status", "reward_snapshot" = EXCLUDED."reward_snapshot", "reply_id" = EXCLUDED."reply_id", "submission" = EXCLUDED."submission", "claimed_at" = EXCLUDED."claimed_at", "submitted_at" = EXCLUDED."submitted_at", "completed_at" = EXCLUDED."completed_at";
