INSERT INTO "task_participations" ("id", "task_id", "user_id", "status", "reward_snapshot", "reply_id", "submission", "claimed_at", "submitted_at", "completed_at") VALUES ('666f9ce2-f36d-44f4-b1b4-228c021193b0', '00000000-0000-0000-0000-000000000023', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', 'rewarded', 180, NULL, '{}', '2026-07-24T08:13:35.017362+00:00', '2026-07-24T08:14:32.763163+00:00', '2026-07-24T08:14:32.763163+00:00') ON CONFLICT ("id") DO UPDATE SET "task_id" = EXCLUDED."task_id", "user_id" = EXCLUDED."user_id", "status" = EXCLUDED."status", "reward_snapshot" = EXCLUDED."reward_snapshot", "reply_id" = EXCLUDED."reply_id", "submission" = EXCLUDED."submission", "claimed_at" = EXCLUDED."claimed_at", "submitted_at" = EXCLUDED."submitted_at", "completed_at" = EXCLUDED."completed_at";
INSERT INTO "task_participations" ("id", "task_id", "user_id", "status", "reward_snapshot", "reply_id", "submission", "claimed_at", "submitted_at", "completed_at") VALUES ('23affc27-456c-4ffd-921e-6a50862696a3', '00000000-0000-0000-0000-000000000020', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', 'rewarded', 500, NULL, '{"body": "FEAR and DREAMS｜把一次现场相遇，变成一辈子的记忆\n\n第一次走进 FEAR and DREAMS 演唱会现场时，我以为自己只是来听一场演唱会。\n\n直到灯光熄灭，音乐响起，全场数万人的欢呼汇聚成同一种心跳，我才发现，这不是一场普通的演出，而是一场关于成长、勇气和梦想的旅程。\n\n陈奕迅没有刻意煽情，却总能用一首歌唱出每个人心里的故事。\n\n当熟悉的旋律响起，身边素不相识的人一起合唱，手机灯光像星海一样铺满整个场馆。那一刻，我们来自不同的城市，有着不同的人生，却因为同一个声音，相遇在同一个夜晚。\n\n《FEAR and DREAMS》让我明白，恐惧从来不会消失，但梦想会给人继续前行的勇气。", "image_urls": ["data:image/jpeg;base64,"]}', '2026-07-24T09:17:27.177199+00:00', '2026-07-24T09:18:10.959605+00:00', '2026-07-24T09:18:10.959605+00:00') ON CONFLICT ("id") DO UPDATE SET "task_id" = EXCLUDED."task_id", "user_id" = EXCLUDED."user_id", "status" = EXCLUDED."status", "reward_snapshot" = EXCLUDED."reward_snapshot", "reply_id" = EXCLUDED."reply_id", "submission" = EXCLUDED."submission", "claimed_at" = EXCLUDED."claimed_at", "submitted_at" = EXCLUDED."submitted_at", "completed_at" = EXCLUDED."completed_at";
INSERT INTO "task_participations" ("id", "task_id", "user_id", "status", "reward_snapshot", "reply_id", "submission", "claimed_at", "submitted_at", "completed_at") VALUES ('7215e91c-740b-4476-a702-651d7a709105', '00000000-0000-0000-0000-000000000005', '6028bbef-57f4-4121-bf31-eb9c7515d7d5', 'rewarded', 80, '22244154-1d78-4e46-836a-e51d36a9237f', '{}', '2026-07-24T09:20:01.122408+00:00', '2026-07-24T09:20:23.138758+00:00', '2026-07-24T09:20:23.138758+00:00') ON CONFLICT ("id") DO UPDATE SET "task_id" = EXCLUDED."task_id", "user_id" = EXCLUDED."user_id", "status" = EXCLUDED."status", "reward_snapshot" = EXCLUDED."reward_snapshot", "reply_id" = EXCLUDED."reply_id", "submission" = EXCLUDED."submission", "claimed_at" = EXCLUDED."claimed_at", "submitted_at" = EXCLUDED."submitted_at", "completed_at" = EXCLUDED."completed_at";

